import{_ as s,y as n,a as i,o as r,a2 as e,D as o}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Taxes","description":"","frontmatter":{},"headers":[],"relativePath":"configure/taxes.md","filePath":"configure/taxes.md","lastUpdated":1789395222000}'),l={name:"configure/taxes.md"};function d(g,t,h,c,u,p){const a=n("ImagePopup");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="taxes" tabindex="-1">Taxes <a class="header-anchor" href="#taxes" aria-label="Permalink to &quot;Taxes&quot;">​</a></h1><p>This screen decides how tax is calculated and how it is shown to shoppers. The tax rates and tax categories themselves are created under <strong>Settings &gt;&gt; Taxes</strong>; see <a href="./../settings/taxes.html">Taxes</a>.</p><p>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Taxes</strong>.</p><h2 id="choose-the-tax-categories" tabindex="-1">Choose the tax categories <a class="header-anchor" href="#choose-the-tax-categories" aria-label="Permalink to &quot;Choose the tax categories&quot;">​</a></h2><ol><li>In <strong>Tax Categories</strong>, choose the <strong>Shipping Tax Category</strong>.</li><li>Choose the <strong>Product Default Tax Category</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),o(a,{src:"/images/configure/taxes-calculation.png",alt:"Tax Categories and Calculation Settings sections of the Taxes screen"}),t[1]||(t[1]=e('<p><strong>Shipping Tax Category:</strong> The tax category used to calculate tax on shipping. If none is chosen, shipping is not taxed.</p><p><strong>Product Default Tax Category:</strong> The tax category used for products that don&#39;t have a tax category of their own.</p><h2 id="decide-how-tax-is-calculated" tabindex="-1">Decide how tax is calculated <a class="header-anchor" href="#decide-how-tax-is-calculated" aria-label="Permalink to &quot;Decide how tax is calculated&quot;">​</a></h2><ol><li>In <strong>Calculation Settings</strong>, choose the options described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th></tr></thead><tbody><tr><td><strong>Calculation Based On</strong></td><td>The address that decides which tax rates apply: <strong>Shipping Address</strong> (the default), <strong>Billing Address</strong>, or <strong>Shipping Origin</strong>, the address set under <a href="./shipping.html">Shipping Settings</a>.</td></tr><tr><td><strong>Product Prices</strong></td><td><strong>Excluding Tax</strong> (the default) when the prices you enter don&#39;t include tax, so tax is added on top. <strong>Including Tax</strong> when they already include it.</td></tr><tr><td><strong>Shipping Prices</strong></td><td>The same choice for shipping rates.</td></tr><tr><td><strong>Apply Tax On</strong></td><td><strong>After Discount</strong> (the default) calculates tax on the price after cart rule discounts. <strong>Before Discount</strong> calculates it on the original price. This applies only to prices that exclude tax.</td></tr></tbody></table><h2 id="set-a-default-destination" tabindex="-1">Set a default destination <a class="header-anchor" href="#set-a-default-destination" aria-label="Permalink to &quot;Set a default destination&quot;">​</a></h2><p>Until a shopper enters an address, tax is calculated for the default destination.</p><ol><li>In <strong>Default Destination Calculation</strong>, choose the <strong>Default Country</strong>.</li><li>Choose the <strong>Default State</strong>.</li><li>Enter the <strong>Default Post Code</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',8)),o(a,{src:"/images/configure/taxes-display.png",alt:"Default Destination Calculation and tax display sections of the Taxes screen"}),t[2]||(t[2]=e('<h2 id="choose-how-tax-is-displayed" tabindex="-1">Choose how tax is displayed <a class="header-anchor" href="#choose-how-tax-is-displayed" aria-label="Permalink to &quot;Choose how tax is displayed&quot;">​</a></h2><p><strong>Shopping Cart Display Settings</strong> decide how tax is shown in the cart and at checkout. <strong>Orders, Invoices, Refunds Display Settings</strong> decide the same for orders, invoices and refunds. Both sections have <strong>Display Prices</strong>, <strong>Display Subtotal</strong> and <strong>Display Shipping Amount</strong>, each with these options:</p><ul><li><strong>Excluding Tax</strong> – the amount without tax. This is the default.</li><li><strong>Including Tax</strong> – the amount with tax.</li><li><strong>Excluding and Including Both</strong> – both amounts.</li></ul><p><strong>Show Tax Breakdown</strong>, in the cart section, lists the tax for each product and tax rate in the cart and checkout summary. It is meant for checking your tax setup, and is off by default.</p>',4))])}const T=s(l,[["render",d]]);export{f as __pageData,T as default};
